const markAgentRuntimeMCPHoldCapable = `-- name: MarkAgentRuntimeMCPHoldCapable :execrows
UPDATE agent_runtime_state ars
SET mcp_hold_capable_at = now()
FROM devices d
WHERE d.id = ars.device_id
  AND ars.device_id = $1
  AND d.org_id = $2
  AND d.kind = 'agent'
  AND d.deleted_at IS NULL
`

type MarkAgentRuntimeMCPHoldCapableParams struct {
	DeviceID uuid.UUID `json:"device_id"`
	OrgID    uuid.UUID `json:"org_id"`
}

// The runtime declared (poll query mcp_hold=true) that it keeps an MCP call
// open while an "Ask first" request waits. Recorded on every declaring poll so
// the value is also a freshness signal. Never cleared by a poll that omits it.
func (q *Queries) MarkAgentRuntimeMCPHoldCapable(ctx context.Context, arg MarkAgentRuntimeMCPHoldCapableParams) (int64, error) {
	result, err := q.db.Exec(ctx, markAgentRuntimeMCPHoldCapable, arg.DeviceID, arg.OrgID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setAgentRuntimeTunnelDNSApplied = `-- name: SetAgentRuntimeTunnelDNSApplied :execrows
UPDATE agent_runtime_state ars
SET tunnel_dns_applied = $1
FROM devices d
WHERE d.id = ars.device_id
  AND ars.device_id = $2
  AND d.org_id = $3
  AND d.kind = 'agent'
  AND d.deleted_at IS NULL
  AND ars.tunnel_dns_applied IS DISTINCT FROM $1
`

type SetAgentRuntimeTunnelDNSAppliedParams struct {
	TunnelDnsApplied *bool     `json:"tunnel_dns_applied"`
	DeviceID         uuid.UUID `json:"device_id"`
	OrgID            uuid.UUID `json:"org_id"`
}

// The runtime reported whether it wrote the pushed DNS servers into its tunnel
// configuration (false: the host has no resolvconf).
func (q *Queries) SetAgentRuntimeTunnelDNSApplied(ctx context.Context, arg SetAgentRuntimeTunnelDNSAppliedParams) (int64, error) {
	result, err := q.db.Exec(ctx, setAgentRuntimeTunnelDNSApplied, arg.TunnelDnsApplied, arg.DeviceID, arg.OrgID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertAgentMCPToolMarker = `-- name: UpsertAgentMCPToolMarker :one
INSERT INTO agent_mcp_tool_markers (org_id, profile_id, tool_name, effect, set_by_user_id)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (profile_id, tool_name) DO UPDATE
SET effect = EXCLUDED.effect, set_by_user_id = EXCLUDED.set_by_user_id
WHERE agent_mcp_tool_markers.org_id = EXCLUDED.org_id
RETURNING org_id, profile_id, tool_name, effect, set_by_user_id, created_at, updated_at
`

type UpsertAgentMCPToolMarkerParams struct {
	OrgID       uuid.UUID   `json:"org_id"`
	ProfileID   uuid.UUID   `json:"profile_id"`
	ToolName    string      `json:"tool_name"`
	Effect      string      `json:"effect"`
	SetByUserID pgtype.UUID `json:"set_by_user_id"`
}

func (q *Queries) UpsertAgentMCPToolMarker(ctx context.Context, arg UpsertAgentMCPToolMarkerParams) (AgentMcpToolMarker, error) {
	row := q.db.QueryRow(ctx, upsertAgentMCPToolMarker,
		arg.OrgID,
		arg.ProfileID,
		arg.ToolName,
		arg.Effect,
		arg.SetByUserID,
	)
	var i AgentMcpToolMarker
	err := row.Scan(
		&i.OrgID,
		&i.ProfileID,
		&i.ToolName,
		&i.Effect,
		&i.SetByUserID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

